// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance && amount < 2**128);
        vm.deal(address(c), amount);
        vm.prank(address(this));
        try c.withdraw(amount) {
            assertTrue(address(c).balance == 0);
        } catch {
            assertTrue(address(c).balance == amount);
        }
    }
    receive() external payable {}
}
